      "most_likely_effort": 16
    },
    {
      "activity_id": "A3",
      "activity_name": "U1 - Unit tests and integration with runtime API",
      "activity_description": "Write unit tests for the command and ensure integration with runtime info APIs works correctly.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A4",
      "activity_name": "U1 - Documentation update",
      "activity_description": "Update user documentation to include the new shell command.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A5",
      "activity_name": "U2 - Research and design YARN deployer",
      "activity_description": "Research YARN deployment model for SCDF and design the deployer SPI implementation.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A6",
      "activity_name": "U2 - Implement YARN deployer SPI",
