    {
      "activity_id": "A8",
      "activity_name": "U2 - Integration testing with Hadoop cluster",
      "activity_description": "Perform integration testing on a Hadoop/YARN cluster to validate streaming and batch pipeline deployment.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A9",
      "activity_name": "U2 - Documentation",
      "activity_description": "Document the YARN deployer configuration and usage.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A10",
      "activity_name": "U3 - Analyze XD file module",
      "activity_description": "Analyze the existing Spring XD file module source code to understand its functionality and dependencies.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A11",
      "activity_name": "U3 - Port to SCS source module",
