    },
    {
      "activity_id": "A14",
      "activity_name": "U4 - Analyze current build and deployer structure",
      "activity_description": "Analyze the current Maven multi-module build and deployer packaging to understand how deployers are bundled.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A15",
      "activity_name": "U4 - Refactor build to separate deployer modules",
      "activity_description": "Refactor the build to produce individual deployer artifacts (JARs) for each SPI deployer.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A16",
      "activity_name": "U4 - Update admin to load deployers dynamically",
