      "most_likely_effort": 24
    },
    {
      "activity_id": "A28",
      "activity_name": "U7 - Documentation",
      "activity_description": "Document the SFTP source module configuration and usage.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A29",
      "activity_name": "U8 - Audit CI pipelines",
      "activity_description": "Audit current CI pipelines for Data Flow and related projects to identify gaps.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A30",
      "activity_name": "U8 - Implement missing pipeline steps",
      "activity_description": "Implement missing pipeline steps such as integration tests, performance tests, and release automation.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A31",
      "activity_name": "U8 - Configure CI for all repos",
      "activity_description": "Configure the CI system (Jenkins/GitHub Actions) for all relevant repositories.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A32",
      "activity_name": "U8 - Test pipelines",
      "activity_description": "Run test executions of the pipelines to verify they work correctly on every commit.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A33",
      "activity_name": "Cross-cutting - Integration testing across modules",
      "activity_description": "Perform end-to-end integration testing across the modules affected by the user stories.",
